appearances.css:
.mk{gap:3px}
.box{padding:4px 5px;gap:3px;border-radius:3px}
.box:first-child{display:flex;flex-wrap:wrap;align-items:flex-start;gap:3px 4px}
.box:first-child>.row{display:contents}
.box:first-child>.row>.ctl{flex:1 1 84px!important;min-width:0!important;gap:2px!important;justify-items:center;align-content:start}
.box:first-child>.row>.ctl>input[type=text]{width:100%;font:inherit;font-size:10px;padding:3px 4px;text-align:center;border-radius:3px;min-height:24px;background:var(--field,var(--card,#1c2128));color:var(--field-fg,var(--fg,#e6e9ee));border:1px solid var(--line,#2a303a)}
.ctl .ctl{flex:none;min-width:0;display:grid;justify-items:center;gap:0;width:100%}
.ctl label:not(.lab){display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:0;font-size:8px;letter-spacing:-.02em;text-transform:none;line-height:1.15;text-align:center;max-width:100%}
.ctl output{font-size:8px;line-height:1.1;letter-spacing:0;white-space:nowrap}
.ctl .kn{order:-1;width:34px!important;height:34px!important;justify-self:center!important}
.ctl .kn svg{width:100%;height:100%}
.row>.ctl>label:not(.lab){display:flex;flex-direction:column;align-items:center;font-size:8px;text-transform:none;letter-spacing:-.02em}
.row>.ctl>.kn{order:-1;width:34px!important;height:34px!important;justify-self:center!important}
.row>.ctl{display:grid}
.ctl label.lab{font-size:9px;letter-spacing:0;text-transform:none;gap:3px;align-items:center;justify-content:center;flex-direction:row}
.box>.lab{display:none}
.empty{padding:5px 8px;line-height:1.3;font-size:9px;border-radius:3px}
.asgbar,.asg{gap:4px}
.mk .prow{grid-template-columns:minmax(56px,1fr) auto minmax(70px,1.3fr) 32px 10px;gap:2px 5px;min-height:20px;font-size:10px}
.mk .prow select{grid-column:auto;font-size:9px;padding:1px 2px;min-height:22px;max-width:54px;border-radius:3px}
.mk .prow output{font-size:9px}
.mk .prow input[type=range]{height:14px}
.mk details.lane{padding:2px 5px;border-radius:3px}
.mk details.lane>summary{font-size:10px;padding:2px 0;letter-spacing:.04em}
.mk .tg h3{font-size:11px;margin:0 0 2px;gap:6px}
.mk .tg h3 small{font-size:9px}
.mk .asgbar input[type=search]{font-size:10px;padding:3px 6px;min-height:24px;flex:1 1 100px}
.mk .asgbar label.lab{font-size:9px;letter-spacing:0;text-transform:none;white-space:nowrap}
